/* ===== game 5: Vendemmia (falling grapes) ===== */
let HVC=null;
function hvCats(){ if(HVC) return HVC; const reg={}; GRAPES.forEach(g=>g.reg.forEach(r=>{ (reg[r]=reg[r]||new Set()).add(g.k); }));
  const out=[]; Object.entries(reg).forEach(([r,s])=>{ if(s.size>=2) out.push({kind:"R",lab:()=>mName(r),ok:s}); });
  try{ const S=schBuild(); S.C.forEach(c=>{ const s=new Set(GRAPES.filter(g=>grapeCountries(g.k).includes(c.id)).map(g=>g.k)); if(s.size>=3&&s.size<=GRAPES.length-6) out.push({kind:"C",lab:()=>c.nm[L()],ok:s}); }); }catch(e){}
  return HVC=out; }
function hvNewCat(G){ const cs=hvCats(); let c; do{ c=cs[Math.floor(Math.random()*cs.length)]; }while(G.cat&&c===G.cat&&cs.length>1); G.cat=c; G.got=0; G.flash=1.6; }
function hvNew(){ const G={score:0,hearts:3,left:75,spr:[],nid:0,spawn:0,speed:70,miss:[],last:0}; hvNewCat(G); return G; }
const bunchSvg=(c)=>{ const f=c==="w"?["#d8e08a","#b9c45a"]:["#7b2a63","#4e1b44"]; let s=`<svg viewBox="0 0 40 46" aria-hidden="true"><path d="M20 2c0 4 0 6-1 9" stroke="#6b4a32" stroke-width="2" fill="none" stroke-linecap="round"/><path d="M21 6c5-3 10-2 13 1-4 3-9 3-13-1z" fill="#6b9a3a"/>`;
  [[4,9],[3,16],[3,23],[2,30],[1,37]].forEach(([n,y],r)=>{ for(let i=0;i<n;i++){ const x=20+(i-(n-1)/2)*8; s+=`<circle cx="${x}" cy="${y+4}" r="4.6" fill="${f[(i+r)%2]}"/><circle cx="${x-1.5}" cy="${y+2.6}" r="1.3" fill="rgba(255,255,255,.55)"/>`; } }); return s+"</svg>"; };
const hvBg=`<svg class="hv-bg" viewBox="0 0 360 520" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="hvsky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#f7d9a8"/><stop offset=".55" stop-color="#f3c9a3"/><stop offset="1" stop-color="#e9b98f"/></linearGradient></defs>
 <rect width="360" height="520" fill="url(#hvsky)"/><circle cx="290" cy="90" r="38" fill="#fbe7b0" opacity=".9"/>
 <path d="M0 330 Q90 290 180 315 T360 300 V520 H0Z" fill="#b9a26b" opacity=".55"/><path d="M0 380 Q120 340 220 370 T360 360 V520 H0Z" fill="#8a9a4a" opacity=".65"/>
 ${[0,1,2,3,4,5].map(i=>`<path d="M${-40+i*80} 520 L${150+i*14} 360" stroke="#5e7a2c" stroke-width="${9-i}" stroke-linecap="round" opacity=".55"/>`).join("")}
 <path d="M0 470 Q180 440 360 470 V520 H0Z" fill="#6b5233" opacity=".7"/></svg>`;
const hvCatHtml=G=>`<div class="hvcat" id="hvcat"><small>${t(G.cat.kind==="R"?"hvCatR":"hvCatC")}</small><b>${esc(G.cat.lab())}</b><span class="hvdots">${[0,1,2,3,4].map(i=>`<i class="${i<G.got?"on":""}"></i>`).join("")}</span></div>`;
function hvRender(){ const G=GM; if(G.fin) return G.fin;
  return `<section class="view gplay hvplay">${gTop(G,Math.max(0,G.left/75),`<div class="mthearts">${[0,1,2].map(i=>heartSvg(i<G.hearts)).join("")}</div>`)}
   ${hvCatHtml(G)}
   <div class="hvstage" id="hvstage">${hvBg}<div class="hvspr" id="hvspr"></div><div class="hvscore"><b id="hvsc">${G.score}</b> 🍇 · <span id="gtime">${Math.ceil(G.left)}</span>s</div></div></section>`; }
function hvLoop(){ const G=GM; if(!G||G.k!=="g_harv"||G.fin) return; const now=performance.now(), dt=Math.min(.05,(now-(G.last||now))/1000); G.last=now;
  const st=$("#hvstage"), box=$("#hvspr"); if(!st||!box){ G.raf=requestAnimationFrame(hvLoop); return; } const H=st.clientHeight;
  G.left-=dt; G.spawn-=dt; if(G.flash>0){ G.flash-=dt; }
  const el=$("#gtime"); if(el) el.textContent=Math.ceil(Math.max(0,G.left)); const pb=$(".mtprog i"); if(pb) pb.style.width=Math.max(0,G.left/75*100)+"%";
  if(G.spawn<=0){ const ok=Math.random()<.45; const okL=GRAPES.filter(g=>G.cat.ok.has(g.k)), noL=GRAPES.filter(g=>!G.cat.ok.has(g.k));
    const g=(ok?okL:noL)[Math.floor(Math.random()*(ok?okL:noL).length)]; const lane=Math.floor(Math.random()*3);
    G.spr.push({id:++G.nid,g,ok:G.cat.ok.has(g.k),x:6+lane*31+Math.random()*4,y:-90,v:G.speed*(.85+Math.random()*.35)}); G.spawn=Math.max(.55,1.25-G.score*.025); }
  G.spr.forEach(s=>{ s.y+=s.v*dt; let d=document.getElementById("hvb"+s.id);
    if(!d){ d=document.createElement("button"); d.type="button"; d.className="hvb "+(s.g.c==="w"?"w":"b"); d.id="hvb"+s.id; d.dataset.hv=s.id; d.innerHTML=bunchSvg(s.g.c)+`<span>${esc(s.g.k)}</span>`; d.style.left=s.x+"%"; box.appendChild(d); }
    d.style.transform=`translateY(${s.y}px) rotate(${Math.sin((s.y+s.id*40)/40)*6}deg)`; });
  G.spr=G.spr.filter(s=>{ if(s.y>H+10){ const d=document.getElementById("hvb"+s.id); if(d) d.remove(); return false; } return true; });
  if(G.left<=0) return hvEnd(); G.raf=requestAnimationFrame(hvLoop); }
function hvFx(x,y,cls,txt){ const st=$("#hvstage"); if(!st) return; const f=document.createElement("div"); f.className="hvfx "+cls; f.style.left=x+"px"; f.style.top=y+"px"; f.textContent=txt; st.appendChild(f); setTimeout(()=>f.remove(),900); }
function hvTap(id,ev){ const G=GM; if(!G||G.k!=="g_harv"||G.fin) return; const s=G.spr.find(z=>z.id===id); if(!s||s.hit) return; s.hit=1;
  const d=document.getElementById("hvb"+id), st=$("#hvstage"), r=d.getBoundingClientRect(), R=st.getBoundingClientRect(), x=r.left-R.left+r.width/2, y=r.top-R.top+r.height/2;
  G.spr=G.spr.filter(z=>z!==s);
  if(s.ok){ G.score++; G.got++; d.classList.add("squish"); setTimeout(()=>d.remove(),380); hvFx(x,y,"good","+1"); mtBeep(true); const sc=$("#hvsc"); if(sc) sc.textContent=G.score;
    if(G.got>=5){ hvNewCat(G); G.speed+=14; G.spr.forEach(z=>{ const e=document.getElementById("hvb"+z.id); if(e) e.remove(); }); G.spr=[]; const c=$("#hvcat"); if(c){ c.outerHTML=hvCatHtml(G); $("#hvcat").classList.add("swap"); } }
    else { const dots=document.querySelectorAll(".hvdots i"); if(dots[G.got-1]) dots[G.got-1].classList.add("on"); } }
  else { G.hearts--; d.classList.add("bad"); setTimeout(()=>d.remove(),450); hvFx(x,y,"bad","✗"); mtBeep(false); st.classList.remove("shake"); void st.offsetWidth; st.classList.add("shake");
    G.miss.push({why:`${s.g.k} ${t("hvNot")} ${G.cat.lab()} → ${s.g.reg.slice(0,4).map(mName).join(", ")}`});
    const hs=document.querySelector(".mthearts"); if(hs) hs.innerHTML=[0,1,2].map(i=>heartSvg(i<G.hearts)).join("");
    if(G.hearts<=0) return hvEnd(); } }
function hvEnd(){ const G=GM; if(G.fin) return; cancelAnimationFrame(G.raf); const xp=G.score*2+5, nb=gAward("g_harv",G.score,xp);
  G.fin=gEnd(G,G.score,t("hvUnit"),xp,nb,G.miss.length?`<div class="gsec2"><h4>${t("gReview")}</h4>${G.miss.slice(0,6).map(m=>`<p>${esc(m.why)}</p>`).join("")}</div>`:""); render(); }
document.addEventListener("pointerdown",e=>{ const b=e.target.closest("[data-hv]"); if(b){ e.preventDefault(); hvTap(+b.dataset.hv,e); } });

/* ===== game 6: Bollicine (rising answers) ===== */
function bbPick(G){ const l=L(); const pool=BANK.filter(b=>!G.used.has(b.id)&&b.q[l].length<=150&&b.o.every(o=>o[l].length<=46));
  const b=pool[Math.floor(Math.random()*pool.length)]||BANK[0]; G.used.add(b.id);
  const ord=shuffle([0,1,2,3]); return {b,bs:ord.map((o,i)=>({o,lane:i%2,delay:i*.75+(i>1?.25:0),pop:0})),t:0,pick:null}; }
function bbNew(){ const G={score:0,lives:3,used:new Set(),dur:10,miss:[]}; G.q=bbPick(G); return G; }
function bbRender(){ const G=GM; if(G.fin) return G.fin; const q=G.q, l=L(), lvl=Math.min(1,G.score/15);
  return `<section class="view gplay bbplay">${gTop(G,lvl,`<div class="mthearts">${[0,1,2].map(i=>heartSvg(i<G.lives)).join("")}</div>`)}
   <p class="mtkind">${esc(chName(q.b.c))} · <b>${G.score}</b> 🫧</p><h2 class="qtext bbq">${esc(q.b.q[l])}</h2>
   <div class="bbflute" id="bbst"><div class="bbfoam"></div><div class="bbwine" style="height:${8+lvl*70}%"></div><div class="bbrise">${Array.from({length:14},(_,i)=>`<i style="left:${5+i*6.7}%;animation-delay:${(i*.37)%3}s;animation-duration:${2.4+(i%4)*.6}s"></i>`).join("")}</div>
   ${q.bs.map((x,i)=>`<button type="button" class="bbb ${q.pick!=null?(x.o===0?"ok":x.o===q.pick?"no":"gone"):""}" data-bb="${x.o}" id="bbb${i}" style="left:${x.lane?50:3}%;transform:translate(${x.tx||0}px,${x.ty==null?400:x.ty}px);opacity:${x.ty==null?0:1}"><span>${esc(q.b.o[x.o][l])}</span></button>`).join("")}</div>
   ${q.pick!=null?`<div class="fbbar ${q.pick===0?"good":"bad"}"><b>${t(q.pick===0?"mtOk2":q.pick===-1?"bbTop":"svNo")}</b><span>${esc((q.b.e||q.b.d)[l])}</span><button type="button" class="btn primary" data-bb-next>${t(G.lives>0?"gNext":"gSee")}</button></div>`:""}
  </section>`; }
function bbLoop(){ const G=GM; if(!G||G.k!=="g_bub"||G.fin||G.q.pick!=null) return; const now=performance.now(), dt=Math.min(.05,(now-(G.last||now))/1000); G.last=now;
  const st=$("#bbst"); if(!st){ G.raf=requestAnimationFrame(bbLoop); return; } const H=st.clientHeight, q=G.q; q.t+=dt;
  let lost=false; q.bs.forEach((x,i)=>{ const el=document.getElementById("bbb"+i); if(!el) return; const p=Math.max(0,(q.t-x.delay)/G.dur);
    const y=(H-10)-(H-10+20)*p, wob=Math.sin((q.t+i)*2.1)*10; x.tx=wob; x.ty=y; el.style.transform=`translate(${wob}px,${y}px)`; el.style.opacity=p<=0?0:1; if(p>=1&&x.o===0) lost=true; });
  if(lost) return bbAns(-1); G.raf=requestAnimationFrame(bbLoop); }
function bbAns(o){ const G=GM; if(!G||G.k!=="g_bub"||G.q.pick!=null) return; cancelAnimationFrame(G.raf); G.q.pick=o; const ok=o===0;
  const id=G.q.b.id, x=P.q[id]||[0,0]; P.q[id]=[x[0]+1,x[1]+(ok?1:0)]; save();
  if(ok){ G.score++; G.dur=Math.max(5.5,G.dur-.35); setTimeout(()=>cheers(10),50); } else { G.lives--; G.miss.push(G.q.b); } mtBeep(ok); render(); }
function bbGo(){ const G=GM; G.last=0; G.raf=requestAnimationFrame(()=>{ G.last=performance.now(); bbLoop(); }); }
document.addEventListener("pointerdown",e=>{ const G=GM; if(!G||G.k!=="g_bub"||G.fin) return; const b=e.target.closest("[data-bb]"); if(b&&G.q.pick==null){ e.preventDefault(); bbAns(+b.dataset.bb); } });
document.addEventListener("click",e=>{ const G=GM; if(!G||G.k!=="g_bub"||G.fin) return; if(!e.target.closest("[data-bb-next]")) return;
  if(G.lives<=0){ const xp=G.score*2+5, nb=gAward("g_bub",G.score,xp); G.fin=gEnd(G,G.score,t("bbUnit"),xp,nb,G.miss.length?`<div class="gsec2"><h4>${t("gReview")}</h4>${G.miss.slice(0,5).map(b=>`<p><b>${esc(b.q[L()])}</b><br>✓ ${esc(b.o[0][L()])}</p>`).join("")}</div>`:""); render(); return; }
  G.q=bbPick(G); render(); window.scrollTo(0,0); bbGo(); });

