const fPress=(x,y,juice,mass)=>`<g><rect x="${x}" y="${y}" width="110" height="46" rx="23" fill="url(#fst)" stroke="#5c646b"/>${[0,1,2,3,4,5,6].map(i=>`<path d="M${x+18+i*12} ${y+6}v34" stroke="#6c757d" stroke-width="1" opacity=".6"/>`).join("")}
  <ellipse cx="${x+55}" cy="${y+23}" rx="40" ry="15" fill="${mass}"><animate attributeName="rx" values="40;22;40" dur="3s" repeatCount="indefinite"/></ellipse><rect x="${x+10}" y="${y+56}" width="90" height="14" rx="4" fill="#5c646b"/><rect x="${x+14}" y="${y+60}" width="82" height="7" rx="3" fill="${juice}"/>${fDrops(x+40,y+46,y+60,juice,3)}${fDrops(x+70,y+46,y+60,juice,3)}</g>`;
const fYeast=(x,y)=>`<g transform="translate(${x} ${y})"><ellipse rx="7" ry="5.5" fill="#efe1b8" stroke="#b39a5c"/><ellipse cx="7" cy="-4" rx="3" ry="2.5" fill="#efe1b8" stroke="#b39a5c"><animate attributeName="rx" values="1;3;1" dur="2s" repeatCount="indefinite"/></ellipse></g>`;
const fGauge=(x,y,to,lab)=>`<g transform="translate(${x} ${y})"><circle r="16" fill="#fbf3e2" stroke="#5c646b" stroke-width="2"/><path d="M-11 8A14 14 0 1 1 11 8" fill="none" stroke="#d4a23a" stroke-width="2"/><path d="M0 0L0 -12" stroke="#8c1d40" stroke-width="2.2" stroke-linecap="round"><animateTransform attributeName="transform" type="rotate" from="-130" to="${to}" dur="3s" fill="freeze"/></path><circle r="2.2" fill="#3a2a2f"/>${fTxt(0,28,lab,9,"#fff4dc")}</g>`;
const fClock=(x,y,lab)=>`<g transform="translate(${x} ${y})"><circle r="14" fill="#fbf3e2" stroke="#d4a23a" stroke-width="2"/><path d="M0 0V-9" stroke="#3a2a2f" stroke-width="2" stroke-linecap="round"><animateTransform attributeName="transform" type="rotate" from="0" to="360" dur="2s" repeatCount="indefinite"/></path><path d="M0 0H6" stroke="#3a2a2f" stroke-width="2" stroke-linecap="round"><animateTransform attributeName="transform" type="rotate" from="0" to="360" dur="24s" repeatCount="indefinite"/></path>${fTxt(0,26,lab,9,"#fff4dc")}</g>`;
const fChip=(x,y,s,bg,fg)=>{ const w_=s.length*6.2+14; x=Math.max(w_/2+3,Math.min(317-w_/2,x)); return fChip0(x,y,s,bg,fg); };
const fChip0=(x,y,s,bg,fg)=>`<g><rect x="${x-s.length*3.1-7}" y="${y-11}" width="${s.length*6.2+14}" height="17" rx="8.5" fill="${bg||"rgba(20,10,14,.62)"}"/>${fTxt(x,y+1.5,s,10,fg||"#fff4dc")}</g>`;
const fPop=(inner,b)=>`<g opacity="0"><animate attributeName="opacity" from="0" to="1" begin="${b||0}s" dur=".5s" fill="freeze"/>${inner}</g>`;
const RED="#7a1530", WHITE="#e9dc8c", ROSE="#f0a3a0";
const FILMS=[];
let FL=null; let flVoice=lsGet("wset3-voice")!=="0"; let FA=null; const FLT=__FLT__;
const FSEC={v:I3("In vigna","Au vignoble","In the vineyard"),c:I3("In cantina","Au chai","In the winery"),s:I3("Spumanti e vini fortificati","Effervescents et vins mutés","Sparkling and fortified wines"),t:I3("Servizio","Service","Service")};
function flSeen(){ return MT.films||{}; }
function renderFilms(){ const seen=flSeen(); let n=0;
  return `<section class="view films"><p class="flintro">${t("flIntro")}</p>${["v","c","s","t"].map(sec=>{ const L_=FILMS.map((f,i)=>[f,i]).filter(([f])=>f.sec===sec); if(!L_.length) return "";
    return `<h2 class="hsec">${esc(tx(FSEC[sec]))}</h2><div class="flgrid">${L_.map(([f,i])=>`<button type="button" class="flcard" data-film="${i}"><span class="flthumb">${f.s[0].v()}<span class="flplay">▶</span><span class="flnum">${++n}</span></span><span class="fltx"><b>${esc(tx(f.t))}</b><span>${f.s.length} ${t("flScenes")}${seen[f.id]?` · ✓ ${t("flSeen")}`:""}</span></span></button>`).join("")}</div>`; }).join("")}</section>`; }
function flDur(sc){ return Math.max(7,Math.min(30,4+tx(sc.c).length*.065)); }
const flLang=()=>["it","fr","en"][L()];
function flT(){ const x=FLT[FILMS[FL.f].id]; return x&&x[flLang()]; }
function renderFilm(){ if(!FL) FL={f:0,s:0,play:true,el:0}; const f=FILMS[FL.f], sc=f.s[FL.s];
  if(FL.end) return `<section class="view film"><div class="flend card">${gfree("n04",150)}<h2>${t("flEnd")}</h2><p><b>${esc(tx(f.t))}</b></p><div class="row"><button type="button" class="btn primary" data-qch="${f.ch}">${t("flTest")}: ${esc(chName(f.ch))}</button></div><div class="row"><button type="button" class="btn" data-fl="again">${t("flAgain")}</button>${FL.f<FILMS.length-1?`<button type="button" class="btn" data-fl="nextfilm">${t("flNext")}</button>`:""}<button type="button" class="btn ghost" data-go="films">${t("flAll")}</button></div></div></section>`;
  return `<section class="view film"><h2 class="fltitle">${esc(tx(f.t))}</h2><div class="flstage" data-fl="toggle">${sc.v()}<span class="flbadge">${FL.s+1}/${f.s.length}</span>${FL.play?"":`<span class="flpaused">▶</span>`}</div>
   <div class="flbar">${f.s.map((_,i)=>`<i class="${i<FL.s?"done":i===FL.s?"cur":""}" data-fljump="${i}"><b style="width:${i<FL.s?100:0}%"></b></i>`).join("")}</div>
   <div class="flcap"><h3>${esc(tx(sc.h))}</h3><p>${esc(tx(sc.c))}</p></div>
   <div class="flctl"><button type="button" class="flb" data-fl="prev" aria-label="prev" ${FL.s?"":"disabled"}>⏮</button><button type="button" class="flb big" data-fl="toggle" aria-label="play">${FL.play?"❚❚":"▶"}</button><button type="button" class="flb" data-fl="next" aria-label="next">⏭</button>
   <button type="button" class="flb voice ${flVoice?"on":""}" data-fl="voice" aria-pressed="${flVoice}">🔊 ${t("flVoice")}</button></div></section>`; }
function flStop(){ try{ speechSynthesis.cancel(); }catch(e){} if(FA){ try{ FA.pause(); }catch(e){} } }
function flSynth(){ try{ const sc=FILMS[FL.f].s[FL.s]; const u=new SpeechSynthesisUtterance(tx(sc.h)+". "+tx(sc.c)); u.lang=["it-IT","fr-FR","en-GB"][L()];
  const vs=speechSynthesis.getVoices().filter(v=>v.lang&&v.lang.slice(0,2)===u.lang.slice(0,2)); if(vs.length) u.voice=vs.find(v=>/natural|premium|enhanced|google/i.test(v.name))||vs[0];
  u.onend=()=>{ if(FL&&FL.u===u) FL.voiceDone=true; }; FL.u=u; speechSynthesis.speak(u); }catch(e){ FL.voiceDone=true; } }
function flSrc(){ return `audio/${flLang()}/${FILMS[FL.f].id}.mp3`; }
function flSpeak(){ flStop(); if(!flVoice||!FL||!FL.play||FL.end) return; FL.voiceDone=false; const T=flT();
  if(!T){ FL.synth=true; flSynth(); return; }
  if(!FA){ FA=new Audio(); FA.preload="auto"; }
  FL.synth=false; const src=flSrc(), fl=FL;
  const go=()=>{ if(FL!==fl||!FL.play) return; const a=T[FL.s], b=T[FL.s+1], ct=FA.currentTime; if(!(ct>=a-.3&&ct<b-.25)){ try{ FA.currentTime=a; }catch(e){} }
    const pr=FA.play(); if(pr&&pr.catch) pr.catch(()=>{ if(FL===fl&&!FL.synth){ FL.synth=true; flSynth(); } }); };
  if(!FA.src.endsWith(src)){ FA.src=src; FA.onerror=()=>{ if(FL===fl&&!FL.synth){ FL.synth=true; flSynth(); } };
    const h=()=>{ FA.removeEventListener("loadedmetadata",h); go(); }; FA.addEventListener("loadedmetadata",h); try{ FA.load(); }catch(e){} }
  else go(); }
function flShow(){ FL.el=0; FL.voiceDone=false; render(); flSpeak(); }
function flTick(){ if(view!=="film"||!FL){ clearInterval(flTick.iv); flTick.iv=null; flStop(); return; } if(!FL.play||FL.end) return;
  FL.el+=.1; const f=FILMS[FL.f], sc=f.s[FL.s], d=flDur(sc), T=flT(); const cur=document.querySelector(".flbar i.cur b");
  const real=flVoice&&T&&FA&&!FL.synth&&FA.src.endsWith(flSrc())&&!FA.paused&&FA.readyState>1;
  let p;
  if(real){ const a=T[FL.s], b=T[FL.s+1]; p=(FA.currentTime-a)/(b-a); if(FA.currentTime>=b-.06||FA.ended){ flStep(1,true); return; } }
  else p=FL.el/d;
  if(cur) cur.style.width=Math.max(0,Math.min(100,p*100))+"%";
  if(!real){ const done=!flVoice?FL.el>=d:FL.synth?((FL.voiceDone&&FL.el>2)||FL.el>d*2.5):FL.el>d*3; if(done) flStep(1); } }
function flStep(dx,cont){ const f=FILMS[FL.f]; FL.s+=dx; if(FL.s<0) FL.s=0;
  if(FL.s>=f.s.length){ FL.s=f.s.length-1; FL.end=true; MT.films=Object.assign({},MT.films,{[f.id]:(+((MT.films||{})[f.id])||0)+1}); MT.xp=(MT.xp||0)+5; saveMT(); flStop(); render(); setTimeout(()=>cheers(18),100); return; }
  if(cont&&FA&&!FA.paused){ FL.el=0; render(); return; } flShow(); }
function flOpen(i){ flStop(); FL={f:i,s:0,play:true,el:0}; view="film"; render(); window.scrollTo(0,0); flSpeak(); if(!flTick.iv) flTick.iv=setInterval(flTick,100); }
document.addEventListener("click",e=>{ const j=e.target.closest("[data-fljump]"); if(j&&FL){ FL.s=+j.dataset.fljump; flShow(); } });
document.addEventListener("click",e=>{ const c=e.target.closest("[data-film]"); if(c){ e.preventDefault(); flOpen(+c.dataset.film); return; }
  const b=e.target.closest("[data-fl]"); if(!b||!FL) return; const a=b.dataset.fl;
  if(a==="toggle"){ FL.play=!FL.play; if(FL.play) flSpeak(); else flStop(); render(); }
  else if(a==="next") flStep(1); else if(a==="prev") flStep(-1);
  else if(a==="voice"){ flVoice=!flVoice; lsSet("wset3-voice",flVoice?"1":"0"); FL.el=0; render(); flSpeak(); }
  else if(a==="again") flOpen(FL.f); else if(a==="nextfilm") flOpen(FL.f+1); });
